A ``quantity`` of 0 costs 0. ``ValueError`` is raised if ``quantity`` is
negative.
"""
if quantity < 0:
    raise ValueError("quantity cannot be negative")

if quantity == 0:
    return 0

# Check if quantity falls into the open-ended (bulk) tier
# If so, the entire order is priced at that tier's flat rate
for first, last, price in tiers:
    if last is None and quantity >= first:
        return quantity * price

# Graduated pricing within finite tiers
total = 0
for first, last, price in tiers:
    if quantity < first:
        break
    top = min(quantity, last)
    total += (top - first + 1) * price
return total
